### Python

```python
# 01串压缩
# 动态规划 + 分组背包

import sys


INF = 10 ** 18


# 计算一个长度为L的连续段中，减少x个字符的最小代价
def calc_run_cost(L, a):
    # f[i][j]：前i个字符，恰好减少j个字符的最小代价
    f = [[INF] * L for _ in range(L + 1)]
    f[0][0] = 0

    for i in range(L):
        for j in range(L):
            if f[i][j] == INF:
                continue

            # 不压缩当前位置
            if f[i + 1][j] > f[i][j]:
                f[i + 1][j] = f[i][j]

            # 从当前位置开始压缩一段长度k
            for k in range(2, L - i + 1):
                nj = j + (k - 1)
                cost = f[i][j] + a[k]
                if f[i + k][nj] > cost:
                    f[i + k][nj] = cost

    res = [INF] * L
    for j in range(L):
        res[j] = f[L][j]
    return res


# 求解单组测试
def solve_case(n, m, s, a):
    need = n - m

    # 拆分连续段
    runs = []
    cnt = 1
    for i in range(1, n):
        if s[i] == s[i - 1]:
            cnt += 1
        else:
            runs.append(cnt)
            cnt = 1
    runs.append(cnt)

    # 分组背包
    dp = [INF] * (need + 1)
    dp[0] = 0

    for L in runs:
        cost_run = calc_run_cost(L, a)
        ndp = [INF] * (need + 1)

        for old in range(need + 1):
            if dp[old] == INF:
                continue
            for dec in range(min(L - 1, need - old) + 1):
                if cost_run[dec] == INF:
                    continue
                val = dp[old] + cost_run[dec]
                if ndp[old + dec] > val:
                    ndp[old + dec] = val

        dp = ndp

    return -1 if dp[need] == INF else dp[need]


def main():
    input = sys.stdin.readline
    t = int(input().strip())
    ans = []

    for _ in range(t):
        n, m = map(int, input().split())
        s = input().strip()
        arr = list(map(int, input().split()))

        # 方便按长度直接取代价，a[k]表示压缩长度k的代价
        a = [0] * (n + 1)
        for i in range(1, n + 1):
            a[i] = arr[i - 1]

        ans.append(str(solve_case(n, m, s, a)))

    print("\n".join(ans))


if __name__ == "__main__":
    main()
```

